 const generate=async()=>{
  if(signal?.aborted||cancelled())throw Error('Generation stopped.');
  let failure='';
  for(let attempt=0;attempt<2;attempt++){
   const useReasoning=reasoning||(attempt>0&&balanced);
   let raw='';const chunks=await local.chat.completions.create({messages:[{role:'system',content:input.systemPrompt||jyotishSystemInstructions},{role:'user',content:input.prompt+(attempt?consultationRetryPrompt(input,failure):'')}],temperature:.2,max_tokens:useReasoning?4096:1600,response_format:{type:'json_object',schema:JSON.stringify(input.schema)},...(balanced?{extra_body:{enable_thinking:useReasoning}}:{}),stream:true});
   for await(const chunk of chunks){if(signal?.aborted||cancelled())throw Error('Generation stopped.');raw+=chunk.choices[0]?.delta?.content||'';onProgress(raw.length);}
   try{const text=renderConsultation(extractFinalAnswer(raw),input),issue=validateLocalAnswer(text,input.pack,{requireSources:false})||validateTimingAnswer(text,input.response||{});if(issue)throw Error(issue);return text}catch(error){failure=error.message;}
  }
  throw Error(failure+' No generic substitute was shown.');
 };
 try{return await Promise.race([generate(),interrupted]);}catch(e){throw Error(e?.message||String(e)||'Local generation failed.');}finally{clearTimeout(timer);signal?.removeEventListener('abort',abort);}
