 const reason=r=>{const fact=input.pack.facts.find(f=>f.id===r?.factId);if(!fact||typeof r.interpretation!=='string'||!r.interpretation.trim())throw Error('The model selected nonexistent chart evidence.');checkClaim(r.interpretation,fact);return '**'+(fact.displayText||fact.text)+'**\n'+r.interpretation.trim()};
